#include <memory>
#include <iostream>

int main() {
    std::auto_ptr<int> p1(new int(100));

    // 1. get(): Access raw pointer, ownership maintained
    int* raw_access = p1.get();
    std::cout << "Access value: " << *raw_access << std::endl;

    // 2. release(): Relinquish ownership
    int* leaked_ptr = p1.release();
    std::cout << "Released pointer address: " << leaked_ptr << std::endl;

    // p1 now holds nullptr. Must manually delete released pointer
    delete leaked_ptr; 

    // 3. reset(): Change managed resource (and delete old one)
    std::auto_ptr<double> p2(new double(3.14));
    p2.reset(new double(2.71)); // Deletes 3.14, manages 2.71
}
